#[test]
fn handles_empty_quoted_values() {
    let content = "DOUBLE=\"\"\nSINGLE=''";
    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(vars.get("DOUBLE"), Some(&String::new()));
    assert_eq!(vars.get("SINGLE"), Some(&String::new()));
}

#[test]
fn handles_mismatched_quotes() {
    let content = "MIX1=\"hello'\nMIX2='hello\"";
    let vars = EnvFileParser::parse(content).unwrap();

    // Mismatched quotes are not stripped
    assert_eq!(vars.get("MIX1"), Some(&"\"hello'".to_string()));
    assert_eq!(vars.get("MIX2"), Some(&"'hello\"".to_string()));
}

#[test]
fn handles_only_opening_quote() {
    let content = "KEY=\"hello";
    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(vars.get("KEY"), Some(&"\"hello".to_string()));
}

#[test]
fn handles_only_closing_quote() {
    let content = "KEY=hello\"";
    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(vars.get("KEY"), Some(&"hello\"".to_string()));
}

#[test]
fn handles_single_quote_character_value() {
    let content = "D=\"\nS='";
    let vars = EnvFileParser::parse(content).unwrap();

    // A lone quote matches both starts_with and ends_with but len < 2
    assert_eq!(vars.get("D"), Some(&"\"".to_string()));
    assert_eq!(vars.get("S"), Some(&"'".to_string()));
}

#[test]
fn handles_nested_quotes() {
    let content = "D=\"it's here\"\nS='say \"hi\"'";
    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(vars.get("D"), Some(&"it's here".to_string()));
    assert_eq!(vars.get("S"), Some(&"say \"hi\"".to_string()));
}

#[test]
fn handles_escaped_quotes_in_double_quoted_value() {
    let content = r#"KEY="escaped \"quotes\" here""#;
    let vars = EnvFileParser::parse(content).unwrap();

    // Parser does not interpret escape sequences; it strips outer quotes
    assert_eq!(
